// PROCESADOR DE TELEGRAM PARA FORESTECH - VERSIÓN FINAL
const update = $json.body || $json;
console.log('🔔 Webhook recibido:', JSON.stringify(update, null, 2));

if (!update.message) {
  console.log('❌ No es un mensaje, ignorando');
  return [];
}

const message = update.message;
const text = message.text || '';
const userId = message.from.id;
const username = message.from.username || message.from.first_name;
const chatId = message.chat.id;

console.log('📨 Mensaje:', text, 'Usuario:', username);

const commands = {
  '/entrada': 'create_entry',
  '/help': 'show_help',
  '/start': 'show_help'
};

let command = null;
let params = [];

if (text.startsWith('/')) {
  const parts = text.trim().split(' ');
  command = parts[0].toLowerCase();
  params = parts.slice(1);
} else if (text.toLowerCase().includes('entrada')) {
  command = '/entrada';
  params = text.split(' ');
}

if (!commands[command]) {
  return [{
    json: {
      action: 'send_message',
      chatId: chatId,
      message: `❌ Comando no reconocido\n\n🤖 **ForeTech Combustibles**\n\n/entrada - Registrar entrada\n/help - Ayuda\n\n📝 Ejemplo:\n/entrada DIESEL 500 15000 Proveedor principal\n\n🏢 ForeTech Colombia`
    }
  }];
}

if (commands[command] === 'create_entry') {
  let fuelType, quantity, unitPrice, supplier, location;

  if (params.length >= 4) {
    fuelType = params[0].toUpperCase();
    quantity = parseFloat(params[1]);
    unitPrice = parseFloat(params[2]);
    supplier = params[3];
    location = params[4] || 'principal';
  } else {
    const textLower = text.toLowerCase();
    const quantityMatch = textLower.match(/(\d+(?:\.\d+)?)\s*(?:galones?|gal)/);
    quantity = quantityMatch ? parseFloat(quantityMatch[1]) : null;
    const priceMatch = textLower.match(/(?:a|precio|costo)\s*(\d+(?:\.\d+)?)/);
    unitPrice = priceMatch ? parseFloat(priceMatch[1]) : null;

    if (textLower.includes('diesel')) fuelType = 'DIESEL';
    else if (textLower.includes('gasolina')) fuelType = 'GASOLINA';
    else if (textLower.includes('extra')) fuelType = 'EXTRA';
    else if (textLower.includes('corriente')) fuelType = 'CORRIENTE';

    const supplierMatch = textLower.match(/proveedor\s+([a-záéíóúñ\s]+)/);
    supplier = supplierMatch ? supplierMatch[1].trim() : 'Proveedor Telegram';

    if (textLower.includes('austria')) location = 'austria';
    else if (textLower.includes('ilusion')) location = 'ilusion';
    else if (textLower.includes('deposito')) location = 'deposito';
    else location = 'principal';
  }

  if (!fuelType || !quantity || !unitPrice || quantity <= 0 || unitPrice < 0) {
    return [{
      json: {
        action: 'send_message',
        chatId: chatId,
        message: `❌ **Datos incompletos**\n\n📝 Formato:\n/entrada DIESEL 500 15000 Proveedor principal\n\n**Tipos:** DIESEL, GASOLINA, EXTRA, CORRIENTE\n**Ubicaciones:** principal, austria, ilusion, deposito\n\n🏢 ForeTech Colombia`
      }
    }];
  }

  if (quantity > 5000) {
    return [{
      json: {
        action: 'send_message',
        chatId: chatId,
        message: `⚠️ **Cantidad excesiva**\nMáximo: 5,000 galones\nSolicitado: ${quantity} galones\n\n🏢 ForeTech Colombia`
      }
    }];
  }

  const totalValue = quantity * unitPrice;
  if (totalValue > 50000000) {
    return [{
      json: {
        action: 'send_message',
        chatId: chatId,
        message: `⚠️ **Valor excesivo**\nMáximo: $50,000,000\nCalculado: $${totalValue.toLocaleString('es-CO')}\n\n🏢 ForeTech Colombia`
      }
    }];
  }

  return [{
    json: {
      action: 'create_movement',
      movementData: {
        fuelType: fuelType,
        quantity: quantity,
        unitPrice: unitPrice,
        supplier: supplier,
        location: location,
        date: new Date().toISOString()
      },
      telegramData: {
        userId: userId,
        username: username,
        chatId: chatId,
        originalMessage: text
      }
    }
  }];
}

if (commands[command] === 'show_help') {
  return [{
    json: {
      action: 'send_message',
      chatId: chatId,
      message: `🤖 **ForeTech Combustibles Bot**\n\n📋 **Comandos:**\n/entrada - Registrar entrada de combustible\n/help - Mostrar esta ayuda\n\n📝 **Formato:**\n/entrada COMBUSTIBLE CANTIDAD PRECIO PROVEEDOR [UBICACION]\n\n**Ejemplo:**\n/entrada DIESEL 500 15000 \"Shell Colombia\" austria\n\n**Combustibles:** DIESEL, GASOLINA, EXTRA, CORRIENTE\n**Ubicaciones:** principal, austria, ilusion, deposito\n\n**Límites:** 5,000 gal máx, $50M máx\n\n🌐 **Servidor:** DigitalOcean\n🏢 **ForeTech Colombia**\n✅ **Sistema Activo**`
    }
  }];
}
